const $=s=>document.querySelector(s);const icon=(id)=>`<svg><use href="#${id}"/></svg>`;let tracked=false,originTracked=false,ai=false,phase='stale',count=0,timer,toastTimer,attached=null,mode='stale';const origin='Savannah Cat Rescue Network';const names=['Pooler Foster Network','Coastal Georgia Foster Network','Pooler Pet Volunteers','Savannah Community Cats','Lowcountry Rescue Exchange','Georgia Foster Resources'];$('.wave').innerHTML=[5,10,15,8,19,13,7,16,20,9,14,6,11,19,8,15,7,12,5,9,17,7,11,5].map(h=>`<i style="height:${h}px"></i>`).join('');function setTrack(v){tracked=v;$('#track').classList.toggle('tracked',v);$('#track').innerHTML=icon(v?'check':'plus')+`<span>${v?'Tracked':'Track this group'}</span>`;$('#track').setAttribute('aria-pressed',v)}function setAI(v){ai=v;document.body.classList.toggle('ai-open',v);$('#aiToggle').classList.toggle('on',v);$('#aiToggle').setAttribute('aria-expanded',v);$('#aiToggle').setAttribute('aria-label',v?'Hide AI activity':'Show AI activity')}
function setPhase(p,n=0){phase=p;count=n;document.body.classList.toggle('gathering',p==='gathering');document.body.classList.toggle('fresh',p==='fresh');let s=p==='gathering'?`Gathering… ${n}/6 groups`:p==='fresh'?'Up to date':'Last refreshed 5 days ago';$('#status').innerHTML=icon(p==='stale'?'clock':p==='fresh'?'check':'refresh')+`<span>${s}</span>`;$('#refreshDetail').textContent=p==='gathering'?'Working in host tab':p==='fresh'?'Refreshed just now · 6 groups':'6 tracked groups';$('#refreshButton').disabled=p==='gathering';$('#refreshButton').innerHTML=icon('refresh')+`<span>${p==='gathering'?'Gathering…':'Refresh'}</span>`;if(p==='gathering'){$('#refreshButton svg').classList.add('spin');$('#hostCount').textContent=`${n} of 6 groups`;$('#hostProgress').textContent=`Reading ${names[n-1]||names[0]}…`;$('#progress').style.width=`${n/6*100}%`;$('#hostGroup').textContent=names[n-1]||names[0];$('#tabName').textContent=names[n-1]||names[0];setTrack(true)}else{$('#hostGroup').textContent=origin;$('#tabName').textContent=origin;setTrack(originTracked)}}
function preset(m){clearInterval(timer);mode=m;document.querySelectorAll('.preview button').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));setAI(m==='ai');originTracked=m==='tracked'||m==='ai';setPhase(m==='gathering'?'gathering':'stale',m==='gathering'?2:0);setTrack(m!=='stale');$('#history').scrollTop=0}document.querySelectorAll('.preview button').forEach(b=>b.onclick=()=>preset(b.dataset.mode));$('#refreshButton').onclick=()=>{clearInterval(timer);setPhase('gathering',1);timer=setInterval(()=>{if(count<6)setPhase('gathering',count+1);else{clearInterval(timer);setPhase('fresh');showToast('Collection refresh complete. Chat stayed open.')}},2100)};$('#stop').onclick=()=>{clearInterval(timer);setPhase('stale');showToast('Gathering stopped. Room remains connected.')};$('#track').onclick=()=>{if(!tracked){originTracked=true;setTrack(true);showToast('Group added to this collection.')}else showToast('Already tracked in this collection.')};$('#aiToggle').onclick=()=>setAI(!ai);$('#hideAI').onclick=()=>setAI(false);$('#menuToggle').onclick=()=>{let v=$('#menu').classList.toggle('open');$('#menuToggle').setAttribute('aria-expanded',v)};function showToast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>showToast(b.dataset.toast));$('#attach').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=()=>{attached=$('#fileInput').files[0]?.name||null;if(attached)showToast(`${attached} selected for public posting (demo only).`)};function send(){const s=$('#compose').value.trim();if(!s&&!attached)return;const a=document.createElement('article');a.className='message';a.innerHTML='<div class="avatar me">You</div><div class="msg"><div class="msg-head"><strong>You</strong><time>Now</time></div><p></p></div>';a.querySelector('p').textContent=s+(attached?` [Attachment: ${attached}]`:'');$('#history').append(a);$('#compose').value='';attached=null;$('#fileInput').value='';$('#history').scrollTop=$('#history').scrollHeight;$('#compose').focus()}$('#sendButton').onclick=send;$('#compose').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};const query=new URLSearchParams(location.search);preset(query.get('state')||'stale');
